int get_direction_index(const char *dir) {
    if (strcmp(dir, "norte") == 0) return 0;
    if (strcmp(dir, "leste") == 0) return 1;
    if (strcmp(dir, "sul") == 0) return 2;
    if (strcmp(dir, "oeste") == 0) return 3;
    return -1;
}

